	if err := Run(t.Context(), opts, []string{"anchor", "resolve", "--repo", repo, "--id", "ANCHOR-1", "--format", "json"}); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "\"VALID\"") {
