	out.Reset()
	if err := Run(t.Context(), opts, []string{"context", "--repo", repo, "--query", "authenticates", "--format", "json"}); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "approved_anchor") {
